def transform(grid):
    h=len(grid); w=len(grid[0]); seen=set(); n=0
    for r in range(h):
        for c in range(w):
            if grid[r][c]==0 or (r,c) in seen: continue
            n+=1; color=grid[r][c]; stack=[(r,c)]; seen.add((r,c))
            while stack:
                y,x=stack.pop()
                for dy in (-1,0,1):
                    for dx in (-1,0,1):
                        a,b=y+dy,x+dx
                        if 0<=a<h and 0<=b<w and (a,b) not in seen and grid[a][b]==color:
                            seen.add((a,b)); stack.append((a,b))
    return [[4]*n+[0]*(6-n)]

